// Get the output from the Orchestrator Agent
const input = $input.first().json;

// n8n AI Agent output is normally available in "output"
const rawOutput =
  input.output ||
  input.text ||
  input.response ||
  JSON.stringify(input);

// Convert to string
const content = String(rawOutput);

// ---------------------------------------------------------
// Helper functions
// ---------------------------------------------------------

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function markdownToHtml(text) {
  let html = escapeHtml(text);

  // Bold: **text**
  html = html.replace(
    /\*\*(.*?)\*\*/g,
    '<strong>$1</strong>'
  );

  // Headings / horizontal separators
  html = html.replace(/^---$/gm, '');

  // Bullet points
  html = html.replace(
    /^\s*[-•]\s+(.*)$/gm,
    '<li>$1</li>'
  );

  // Wrap consecutive list items
  html = html.replace(
    /(<li>.*?<\/li>\s*)+/gs,
    match => `<ul>${match}</ul>`
  );

  // Line breaks
  html = html.replace(/\n/g, '<br>');

  return html;
}

// ---------------------------------------------------------
// Extract the three sections from Orchestrator output
// ---------------------------------------------------------

function extractSection(startPatterns, endPatterns) {
  let start = -1;
  let end = content.length;

  for (const pattern of startPatterns) {
    const regex = new RegExp(pattern, 'i');
    const match = regex.exec(content);

    if (match) {
      start = match.index + match[0].length;
      break;
    }
  }

  if (start === -1) {
    return '';
  }

  for (const pattern of endPatterns) {
    const regex = new RegExp(pattern, 'i');
    const remaining = content.substring(start);
    const match = regex.exec(remaining);

    if (match) {
      end = start + match.index;
      break;
    }
  }

  return content.substring(start, end).trim();
}

// ---------------------------------------------------------
// Extract Fundamental Analysis
// ---------------------------------------------------------

const fundamental = extractSection(
  [
    'Fundamental\\s+(?:Insights|Analysis)',
    '📌\\s*Fundamental'
  ],
  [
    'Technical\\s+(?:Insights|Analysis)',
    '📈\\s*Technical'
  ]
);

// ---------------------------------------------------------
// Extract Technical Analysis
// ---------------------------------------------------------

const technical = extractSection(
  [
    'Technical\\s+(?:Insights|Analysis)',
    '📈\\s*Technical'
  ],
  [
    'Final\\s+Summary',
    '🎯\\s*Final'
  ]
);

// ---------------------------------------------------------
// Extract Final Summary
// ---------------------------------------------------------

const summary = extractSection(
  [
    'Final\\s+Summary',
    '🎯\\s*Final'
  ],
  []
);

// ---------------------------------------------------------
// Fallback if section extraction doesn't work
// ---------------------------------------------------------

const fundamentalHtml = fundamental
  ? markdownToHtml(fundamental)
  : '<p>No fundamental analysis data available.</p>';

const technicalHtml = technical
  ? markdownToHtml(technical)
  : '<p>No technical analysis data available.</p>';

const summaryHtml = summary
  ? markdownToHtml(summary)
  : '<p>No final summary available.</p>';

// ---------------------------------------------------------
// Current date
// ---------------------------------------------------------

const generatedDate = new Date().toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata',
  dateStyle: 'medium',
  timeStyle: 'short'
});

// ---------------------------------------------------------
// Create professional HTML email
// ---------------------------------------------------------

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">

<style>

body {
  margin: 0;
  padding: 0;
  background-color: #f4f6f8;
  font-family: Arial, Helvetica, sans-serif;
  color: #263238;
}

.container {
  max-width: 850px;
  margin: 20px auto;
  background: #ffffff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 12px rgba(0,0,0,0.10);
}

.header {
  background: linear-gradient(135deg, #172554, #2563eb);
  color: white;
  padding: 25px 30px;
}

.header h1 {
  margin: 0;
  font-size: 25px;
}

.header p {
  margin: 8px 0 0;
  font-size: 13px;
  opacity: 0.9;
}

.section {
  margin: 22px 25px;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid #e5e7eb;
}

.section-title {
  padding: 13px 18px;
  font-size: 18px;
  font-weight: bold;
  color: white;
}

.fundamental-title {
  background: linear-gradient(90deg, #047857, #10b981);
}

.technical-title {
  background: linear-gradient(90deg, #1d4ed8, #3b82f6);
}

.summary-title {
  background: linear-gradient(90deg, #b45309, #f59e0b);
}

.section-content {
  padding: 18px 20px;
  line-height: 1.6;
  font-size: 14px;
  background: #ffffff;
}

.section-content ul {
  padding-left: 22px;
}

.section-content li {
  margin-bottom: 7px;
}

.summary-content {
  background: #fffbeb;
}

.footer {
  text-align: center;
  padding: 18px;
  font-size: 11px;
  color: #6b7280;
  background: #f9fafb;
}

strong {
  color: #111827;
}

</style>

</head>

<body>

<div class="container">

  <!-- HEADER -->

  <div class="header">
    <h1>📊 Stock & Crypto Analysis Report</h1>
    <p>AI-powered Fundamental + Technical Analysis</p>
    <p>Generated: ${generatedDate}</p>
  </div>


  <!-- FUNDAMENTAL ANALYSIS -->

  <div class="section">

    <div class="section-title fundamental-title">
      📌 Fundamental Analysis
    </div>

    <div class="section-content">
      ${fundamentalHtml}
    </div>

  </div>


  <!-- TECHNICAL ANALYSIS -->

  <div class="section">

    <div class="section-title technical-title">
      📈 Technical Analysis
    </div>

    <div class="section-content">
      ${technicalHtml}
    </div>

  </div>


  <!-- FINAL SUMMARY -->

  <div class="section">

    <div class="section-title summary-title">
      🎯 Final Summary
    </div>

    <div class="section-content summary-content">
      ${summaryHtml}
    </div>

  </div>


  <div class="footer">
    This report is generated automatically by your Stock & Crypto Analysis Agent.
    <br>
    Information is for research and educational purposes only and should not be
    considered financial advice.
  </div>

</div>

</body>
</html>
`;

// ---------------------------------------------------------
// Return data for Gmail node
// ---------------------------------------------------------

return [
  {
    json: {
      ...input,

      subject: `📊 Stock & Crypto Analysis Report - ${generatedDate}`,

      emailHtml: html,

      // Keep original AI output available for debugging
      rawAnalysis: content
    }
  }
];
